    //         "tpOrdPx": "",
    //         "tpTriggerPx": "",
    //         "tpTriggerPxType": "",
    //         "triggerPx": "50000",
    //         "triggerPxType": "last",
    //         "triggerTime": "",
    //         "uly": "BTC-USDT"
    //     }
    //
    market := ccxt.GetArg(optionalArgs, 0, nil)
